def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opps = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)

    if not alive_opps:
        safe_bid = DAILY_SALARY * 0.35
        if hp <= 2 or no_water >= 1:
            safe_bid = DAILY_SALARY * 0.6
        return float(min(budget, safe_bid))

    prev_bids = []
    desperate_count = 0
    rich_count = 0
    cindy_like_present = False

    for opp in alive_opps:
        if opp.get('budget', 0) >= 200:
            rich_count += 1
        if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1

        prev = opp.get('previous_trace', {})
        if prev:
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if bid >= 130:
                    cindy_like_present = True

    highest_prev = max(prev_bids) if prev_bids else 0.0
    low_prev = []
    for b in prev_bids:
        if b < 100:
            low_prev.append(b)
    pressure_bid = max(low_prev) if low_prev else 0.0

    tight_supply = supply <= 17
    ample_supply = supply >= 22

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water >= 2:
        urgency += 3
    elif no_water >= 1:
        urgency += 2

    if tight_supply:
        urgency += 2
    elif ample_supply:
        urgency -= 1

    urgency += min(desperate_count, 2)

    if cindy_like_present and urgency <= 1 and ample_supply:
        return float(min(budget, 8.0))

    if cindy_like_present and urgency <= 2 and not tight_supply:
        base = max(18.0, pressure_bid + 2.0)
        return float(min(budget, base))

    if urgency >= 6:
        bid = max(92.0, pressure_bid + 8.0)
    elif urgency >= 4:
        bid = max(68.0, pressure_bid + 5.0)
    elif urgency >= 2:
        bid = max(42.0, pressure_bid + 3.0)
    else:
        bid = max(22.0, pressure_bid + 1.5)

    if highest_prev >= 130 and urgency < 5:
        bid = min(bid, 75.0)

    if rich_count >= 2 and tight_supply:
        bid += 8.0

    if day >= 8:
        bid += 6.0
    if day >= 9 and (hp <= 4 or no_water >= 1):
        bid += 10.0

    return float(min(budget, max(0.0, bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 10.0)
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        if my_status['hp'] <= 3:
            return min(my_status['budget'], float(highest_prev_bid + 5.0))
        if day_context['supply'] < (len(alive_opponents) + 1) * WATER_REQ:
            return min(my_status['budget'], float(highest_prev_bid + 1.0))
        return min(my_status['budget'], float(highest_prev_bid * 0.9))
    return min(my_status['budget'], float(DAILY_SALARY * 0.5))
